SELECT sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, d.d_year, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_net_loss) AS total_net_loss, AVG(cr.cr_return_tax) AS avg_return_tax, CASE WHEN SUM(cr.cr_net_loss) > 5000 THEN 'High Loss' WHEN SUM(cr.cr_net_loss) BETWEEN 1000 AND 5000 THEN 'Medium Loss' ELSE 'Low Loss' END AS loss_category, DENSE_RANK() OVER (PARTITION BY d.d_year ORDER BY SUM(cr.cr_net_loss) DESC) AS net_loss_rank FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY sm.sm_ship_mode_id, sm.sm_type, sm.sm_carrier, d.d_year ORDER BY d.d_year, net_loss_rank
